# 5. Batch Processing (v3)
# ─────────────────────────────────────────────────────────────────────────────

# ── Where the last run went ────────────────────────────────────────────────
#
# v1.3.1: Section 8 used to carry a hard-coded path to somebody's Downloads
# folder, and a run and the plots of that run were connected only by the
# reader retyping it. Both entry points record where they wrote.
LAST_OUTPUT_DIR = None      # Path, set by batch_maple() and launch_maple_gui()

# The per-structure summary, one definition. Section 8 and Hopper both open
# maple_summary.csv and read these names.
SUMMARY_COLS = ["compound", "space_group", "Z", "d_ref_ang",
                "madelung_factor", "total_maple", "disordered",
                "disorder_status", "partial_sublattice", "d_min_ang",
                "geometry_flag", "geometry_status",
                "source_cif", "maplepy_version"]


def _write_outputs(dfs, failed, output_dir):
    """
    Write the three CSVs a MAPLE run produces, and record where they went.

    v1.3.1: batch_maple() wrote maple_results.csv and maple_failed.csv but not
    maple_summary.csv, while the GUI wrote all three. Section 8 and Hopper
    both look for the summary first, so a batch run could not be plotted or
    decomposed and nothing said why. Written in one place now, so the two
    entry points cannot drift again.

    Returns (master, summary); both empty frames if nothing was processed.
    """
    global LAST_OUTPUT_DIR

    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    if dfs:
        master = pd.concat(dfs, ignore_index=True)
        master["maplepy_version"] = MAPLEPY_VERSION
        results_csv = output_dir / 'maple_results.csv'
        master.to_csv(results_csv, index=False)
        print(f"\nSaved {len(master)} rows → {results_csv}")

        summary = (master[SUMMARY_COLS]
                   .drop_duplicates(subset="source_cif")
                   .reset_index(drop=True))
        summary_csv = output_dir / 'maple_summary.csv'
        summary.to_csv(summary_csv, index=False)
        print(f"Saved {len(summary)} structures → {summary_csv}")
    else:
        master = pd.DataFrame()
        summary = pd.DataFrame()
        print("\nNo structures processed successfully.")

    if failed:
        failed_df = pd.DataFrame(failed, columns=['cif_file', 'error'])
        failed_csv = output_dir / 'maple_failed.csv'
        failed_df.to_csv(failed_csv, index=False)
        print(f"Saved {len(failed)} failures → {failed_csv}")

    LAST_OUTPUT_DIR = output_dir
    return master, summary


def process_one_cif(cif_path, oxidation_states=None, data_dir=None,
                    verbose=False):
    """
    Load, compute and tabulate ONE CIF. The one definition.

    v1.3.4: batch_maple and the GUI each had their own copy of this sequence,
    which is two things to keep in step and two things to put in a worker.
    Returns only picklable data, so it can run in another process:

        (name, df or None, error or None, tag, console output)

    `tag` is the mean-field marker for the progress line, so the caller can
    print without reaching back into the result.
    """
    import contextlib as _ctx
    import io as _io
    from pathlib import Path as _P

    name = _P(cif_path).name
    # v1.3.4: the console output is CAPTURED and handed back, not left to
    # wherever this happens to run. load_structure prints which source the
    # oxidation states came from, unconditionally, and that line is the only
    # record of the provenance anywhere - it is in no CSV. A worker process
    # writes it to a pipe nobody reads, so a parallel run would have quietly
    # stopped telling you. Captured here, printed by the caller, identical
    # either way.
    _said = _io.StringIO()
    try:
        with _ctx.redirect_stdout(_said):
            s = load_structure(cif_path, oxidation_states=oxidation_states,
                               data_dir=data_dir)
            result = compute_maple(s, verbose=verbose)
            df = results_to_dataframe(result)
        df["source_cif"] = name
        return (name, df, None, (" [MF]" if result["disordered"] else ""),
                _said.getvalue())
    except Exception as e:
        return name, None, str(e), "", _said.getvalue()


def _resolve_workers(workers, n_items):
    """How many processes to actually start. Never more than there is work."""
    if workers in (None, 1, 0):
        return 1
    if workers == 'auto':
        try:
            import os as _os
            workers = max(1, (_os.cpu_count() or 2) - 2)
        except Exception:
            return 1
    try:
        workers = int(workers)
    except (TypeError, ValueError):
        print(f"  MAPLE_WORKERS = {workers!r} is not a number or 'auto'; "
              f"running serially.")
        return 1
    return max(1, min(workers, n_items))


def _map_cifs(paths, oxidation_states_map, data_dir, verbose, workers):
    """
    process_one_cif over every path, in order, serially or in a pool.

    v1.3.4: the only place that decides between the two, and both branches
    call the same function. A pool that will not start is reported in full
    and the run continues serially - an optimisation with an exact serial
    equivalent should never be the thing that stops the science.
    """
    from pathlib import Path as _P
    n = _resolve_workers(workers, len(paths))
    jobs = [(p, (oxidation_states_map or {}).get(_P(p).stem)) for p in paths]

    if n > 1:
        try:
            from joblib import Parallel, delayed
        except ImportError as e:
            print(f"  joblib is not installed ({e}), so MAPLE_WORKERS "
                  f"cannot be honoured. Running serially. `pip install "
                  f"joblib` for the parallel path.")
            n = 1
    if n > 1:
        print(f"  processing on {n} workers")
        try:
            try:
                # joblib >= 1.3 streams results in order, so progress is
                # visible during the run rather than only at the end
                out = Parallel(n_jobs=n, backend='loky',
                               return_as='generator')(
                    delayed(process_one_cif)(p, oxi, data_dir, False)
                    for p, oxi in jobs)
            except TypeError:
                out = Parallel(n_jobs=n, backend='loky')(
                    delayed(process_one_cif)(p, oxi, data_dir, False)
                    for p, oxi in jobs)
            for item in out:
                yield item
            return
        except Exception as e:
            print(f"  the worker pool failed to run ({type(e).__name__}: "
                  f"{e}). Falling back to serial processing; the results are "
                  f"the same either way, only slower.")

    for p, oxi in jobs:
        yield process_one_cif(p, oxi, data_dir, verbose)


def batch_maple(cif_dir, output_dir=None, oxidation_states_map=None,
                data_dir=None, verbose=False, workers=None):
    """
    Process all CIFs in a directory.

    Parameters
    ----------
    cif_dir : str or Path
        Directory containing CIF files.
    output_dir : str or Path, optional
        Directory for output CSVs. If None, creates 'outputs' inside cif_dir.
    oxidation_states_map : dict  {filename_stem: {element: oxi_state}}
        For CIFs without embedded oxidation states.
    data_dir : str or None
        Folder holding maple_library.json and common_oxidation_states.json.
        None (v1.3.1) means DEFAULT_DATA_DIR, resolved at load. It used to be
        '.', which was passed on explicitly and so overrode that resolution:
        every batch run silently lost two levels of the oxidation-state
        priority chain.
    verbose : bool
        If True, print full MAPLE output per structure.

    Returns
    -------
    pd.DataFrame, one row per site per structure
    """
    cif_dir   = Path(cif_dir)
    cif_files = sorted(cif_dir.glob("*.cif"))
    if not cif_files:
        print(f"No CIF files found in {cif_dir}")
        return pd.DataFrame()

    # ── Create output directory ───────────────────────────────────────────
    if output_dir is None:
        from datetime import datetime
        timestamp  = datetime.now().strftime('%Y%m%d_%H%M%S')
        output_dir = cif_dir / f'outputs_{timestamp}'
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    print(f"Processing {len(cif_files)} CIFs in {cif_dir}")
    print(f"Output directory: {output_dir}")
    dfs, failed = [], []

    # v1.3.4: one worker function, run serially or on a pool by _map_cifs.
    for name, df_i, err, tag, said in _map_cifs(
            [str(p) for p in cif_files], oxidation_states_map, data_dir,
            verbose, MAPLE_WORKERS if workers is None else workers):
        if said:
            print(said, end='')
        if err is not None:
            failed.append((name, err))
            print(f"  ✗ {name:45s}  {err}")
            continue
        dfs.append(df_i)
        print(f"  ✓ {name:45s}  "
              f"MAPLE = {df_i['total_maple'].iloc[0]:.1f} kcal/mol{tag}")

    # ── Save results ──────────────────────────────────────────────────────
    master, _summary = _write_outputs(dfs, failed, output_dir)

    # ── Summary ───────────────────────────────────────────────────────────
    n_total = len(cif_files)
    n_ok    = len(dfs)
    n_fail  = len(failed)
    n_ordered    = sum(1 for d in dfs
                       if not d["disordered"].iloc[0]) if dfs else 0
    n_disordered = n_ok - n_ordered

    print(f"\n{'='*60}")
    print(f"  Total CIFs        : {n_total}")
    print(f"  Processed (OK)    : {n_ok}  "
          f"({n_ordered} ordered, {n_disordered} mean-field)")
    print(f"  Failed            : {n_fail}")
    print(f"{'='*60}")

    return master


